"use client";

import {
  DropdownMenu,
  DropdownMenuContent,
  DropdownMenuTrigger,
} from "../ui/dropdown-menu";
import { Button } from "../ui/button";
import { ArrowUpDown } from "lucide-react";
import { Badge } from "../ui/badge";
import type { UseCriteriaReturn } from "../../types/use-criteria.type";
import { SortingPopover } from "./sorting-popover";
import { SortingList } from "./sorting-list";
import { useSortingAdapter } from "../../hooks/use-sorting-adapter";

export interface SortingField {
  field: string;
  fieldLabel: string;
}

export interface SortingIntegrationProps<T = unknown> {
  fields: SortingField[];
  criteria: UseCriteriaReturn<T>;
}

export function Sorting<T = unknown>({ fields, criteria }: SortingIntegrationProps<T>) {
  const { updateSort, reorderSort } = useSortingAdapter(criteria);

  const sortingCount = criteria.sorting.length;
  const hasSorting = sortingCount > 0;

  return (
    <DropdownMenu>
      <DropdownMenuTrigger asChild>
        <Button variant="outline" size="sm" className="h-8 relative">
          <ArrowUpDown className="h-4 w-4" />
          Sort
          {hasSorting && (
            <Badge className="text-[10px] rounded bg-secondary size-[18px] text-foreground">
              {sortingCount}
            </Badge>
          )}
        </Button>
      </DropdownMenuTrigger>
      <DropdownMenuContent className="w-[450px] p-4" align="start">
        {!hasSorting ? (
          <div className="space-y-0.5 mb-4">
            <p className="font-semibold">No sorting applied</p>
            <p className="text-sm text-muted-foreground">
              Add sorting to your query
            </p>
          </div>
        ) : (
          <div className="space-y-4 mb-4">
            <p className="font-semibold">Sort By</p>
            <SortingList
              sorting={criteria.sorting}
              fields={fields}
              onUpdate={updateSort}
              onRemove={criteria.removeSort}
              onReorder={reorderSort}
            />
          </div>
        )}
        <SortingPopover
          sorting={criteria.sorting}
          fields={fields}
          onAdd={criteria.addSort}
          onClear={criteria.clearSort}
        />
      </DropdownMenuContent>
    </DropdownMenu>
  );
}

"use client";

import * as React from "react";
import { ListOrdered, Search, X } from "lucide-react";
import { Button } from "../ui/button";
import { Input } from "../ui/input";
import { Popover, PopoverContent, PopoverTrigger } from "../ui/popover";
import type { Order, FieldPath, OrderDirection } from "@woltz/rich-domain";
import type { SortingField } from "./sorting";

interface SortingPopoverProps<T = unknown> {
  fields: SortingField[];
  sorting: Order[];
  onAdd: (field: FieldPath<T>, direction?: OrderDirection) => void;
  onClear: () => void;
}

export function SortingPopover<T = unknown>({
  fields,
  sorting,
  onAdd,
  onClear,
}: SortingPopoverProps<T>) {
  const [isOpen, setIsOpen] = React.useState(false);
  const [search, setSearch] = React.useState("");

  const usedFields = sorting.map((sort) => sort.field);
  const remainingFields = fields.filter(
    (field) => !usedFields.includes(field.field)
  );

  const HAS_FIELDS_REMAINING = remainingFields.length > 0;

  const filteredRemainingFields = remainingFields.filter((field) =>
    field.fieldLabel.toLowerCase().includes(search.toLowerCase())
  );

  const handleSelectField = (field: SortingField) => {
    onAdd(field.field as FieldPath<T>, "asc");
    setSearch("");
    setIsOpen(false);
  };

  const handleOpenChange = (open: boolean) => {
    setIsOpen(open);
    if (!open) {
      setSearch("");
    }
  };

  return (
    <div className="flex items-center gap-2">
      <Popover open={isOpen} onOpenChange={handleOpenChange}>
        <PopoverTrigger asChild>
          <Button
            variant="outline"
            size="sm"
            className="h-8 gap-1.5 bg-transparent"
            disabled={!HAS_FIELDS_REMAINING}
          >
            <ListOrdered className="h-4 w-4" />
            Add Sort
          </Button>
        </PopoverTrigger>
        <PopoverContent className="p-0 bg-card w-fit" align="start">
          <div className="p-2 border-b border-border">
            <div className="relative">
              <Search className="absolute left-2 top-1/2 h-4 w-4 -translate-y-1/2 text-muted-foreground" />
              <Input
                placeholder="Search fields..."
                value={search}
                onChange={(e) => setSearch(e.target.value)}
                className="h-8 pl-8"
              />
            </div>
          </div>
          <div className="max-h-60 overflow-y-auto p-1">
            {filteredRemainingFields.map((field) => (
              <button
                key={field.field}
                onClick={() => handleSelectField(field)}
                className="flex w-full items-center gap-2 rounded-sm px-2 py-1.5 text-sm hover:bg-accent"
              >
                <span className="flex-1 text-left">{field.fieldLabel}</span>
              </button>
            ))}
            {filteredRemainingFields.length === 0 && (
              <div className="py-6 text-center text-sm text-muted-foreground">
                {search ? "No fields found" : "All fields are already in use"}
              </div>
            )}
          </div>
        </PopoverContent>
      </Popover>
      <Button
        variant="outline"
        size="sm"
        className="h-8 gap-1.5"
        onClick={onClear}
      >
        <X className="h-4 w-4" />
        Clear Sorting
      </Button>
    </div>
  );
}

"use client";

import { useMemo } from "react";
import {
  DndContext,
  closestCenter,
  KeyboardSensor,
  PointerSensor,
  useSensor,
  useSensors,
  type DragEndEvent,
} from "@dnd-kit/core";
import {
  SortableContext,
  sortableKeyboardCoordinates,
  verticalListSortingStrategy,
} from "@dnd-kit/sortable";
import type { Order, OrderDirection } from "@woltz/rich-domain";
import type { SortingField } from "./sorting";
import { SortingRow } from "./sorting-row";

interface SortingListProps {
  sorting: Order[];
  fields: SortingField[];
  onUpdate: (index: number, field: string, direction: OrderDirection) => void;
  onRemove: (index: number) => void;
  onReorder: (fromIndex: number, toIndex: number) => void;
}

export function SortingList({
  sorting,
  fields,
  onUpdate,
  onRemove,
  onReorder,
}: SortingListProps) {
  const sensors = useSensors(
    useSensor(PointerSensor),
    useSensor(KeyboardSensor, {
      coordinateGetter: sortableKeyboardCoordinates,
    })
  );

  const handleDragEnd = (event: DragEndEvent) => {
    const { active, over } = event;

    if (over && active.id !== over.id) {
      const oldIndex = Number(active.id);
      const newIndex = Number(over.id);

      if (oldIndex !== -1 && newIndex !== -1) {
        onReorder(oldIndex, newIndex);
      }
    }
  };

  const getAvailableFieldsForRow = (currentField: string) => {
    const usedFields = sorting.map((sort) => sort.field);
    return fields.filter(
      (field) =>
        field.field === currentField || !usedFields.includes(field.field)
    );
  };

  const items = useMemo(() => sorting.map((_, i) => i), [sorting]);

  return (
    <DndContext
      sensors={sensors}
      collisionDetection={closestCenter}
      onDragEnd={handleDragEnd}
    >
      <SortableContext items={items} strategy={verticalListSortingStrategy}>
        <div className="space-y-2">
          {sorting.map((sort, index) => (
            <SortingRow
              key={`${sort.field}-${index}`}
              id={index}
              sort={sort}
              fields={getAvailableFieldsForRow(sort.field)}
              onUpdate={(field, direction) => onUpdate(index, field, direction)}
              onRemove={() => onRemove(index)}
            />
          ))}
        </div>
      </SortableContext>
    </DndContext>
  );
}

"use client";

import { useSortable } from "@dnd-kit/sortable";
import { CSS } from "@dnd-kit/utilities";
import { GripVertical, X, ArrowUp, ArrowDown } from "lucide-react";
import type { Order, OrderDirection } from "@woltz/rich-domain";
import type { SortingField } from "./sorting";
import { Button } from "../ui/button";
import {
  Select,
  SelectContent,
  SelectItem,
  SelectTrigger,
  SelectValue,
} from "../ui/select";
import { cn } from "../../lib/utils";

interface SortingRowProps {
  id: number;
  sort: Order;
  fields: SortingField[];
  onUpdate: (field: string, direction: OrderDirection) => void;
  onRemove: () => void;
}

export function SortingRow({
  id,
  sort,
  fields,
  onUpdate,
  onRemove,
}: SortingRowProps) {
  const {
    attributes,
    listeners,
    setNodeRef,
    transform,
    transition,
    isDragging,
  } = useSortable({ id });

  const style = {
    transform: CSS.Transform.toString(transform),
    transition,
  };

  const currentField = fields.find((f) => f.field === sort.field);
  const fieldLabel = currentField?.fieldLabel || sort.field;

  const toggleDirection = () => {
    const newDirection: OrderDirection =
      sort.direction === "asc" ? "desc" : "asc";
    onUpdate(sort.field, newDirection);
  };

  return (
    <div
      ref={setNodeRef}
      style={style}
      className={cn(
        "flex items-center gap-2 p-2 rounded-md border bg-card",
        isDragging && "opacity-50 shadow-lg"
      )}
    >
      <button
        className="cursor-grab active:cursor-grabbing text-muted-foreground hover:text-foreground touch-none"
        {...attributes}
        {...listeners}
      >
        <GripVertical className="h-4 w-4" />
      </button>

      <Select
        value={sort.field}
        onValueChange={(value) => onUpdate(value, sort.direction)}
      >
        <SelectTrigger size="sm" className="h-8 flex-1">
          <SelectValue>{fieldLabel}</SelectValue>
        </SelectTrigger>
        <SelectContent>
          {fields.map((field) => (
            <SelectItem key={field.field} value={field.field}>
              {field.fieldLabel}
            </SelectItem>
          ))}
        </SelectContent>
      </Select>

      <Button
        variant="outline"
        size="sm"
        className="h-8 w-[70px] gap-1.5"
        onClick={toggleDirection}
      >
        {sort.direction === "asc" ? (
          <>
            <ArrowUp className="h-3.5 w-3.5" />
            <span className="text-xs">Asc</span>
          </>
        ) : (
          <>
            <ArrowDown className="h-3.5 w-3.5" />
            <span className="text-xs">Desc</span>
          </>
        )}
      </Button>

      <Button
        variant="ghost"
        size="sm"
        className="h-8 w-8 p-0"
        onClick={onRemove}
      >
        <X className="h-4 w-4" />
      </Button>
    </div>
  );
}

import { useCallback } from "react";
import type { FieldPath, OrderDirection } from "@woltz/rich-domain";
import type { UseCriteriaReturn } from "../types/use-criteria.type";

export interface UseSortingAdapterReturn {
  updateSort: (index: number, field: string, direction: OrderDirection) => void;
  reorderSort: (fromIndex: number, toIndex: number) => void;
}

export function useSortingAdapter<T>(
  criteria: UseCriteriaReturn<T>
): UseSortingAdapterReturn {
  const updateSort = useCallback(
    (index: number, field: string, direction: OrderDirection) => {
      const currentSorting = [...criteria.sorting];
      const sortToUpdate = currentSorting[index];

      if (!sortToUpdate) return;

      currentSorting[index] = { field, direction };

      criteria.clearSort();
      currentSorting.forEach((sort) => {
        criteria.addSort(sort.field as FieldPath<T>, sort.direction);
      });
    },
    [criteria]
  );

  const reorderSort = useCallback(
    (fromIndex: number, toIndex: number) => {
      const currentSorting = [...criteria.sorting];
      const [movedItem] = currentSorting.splice(fromIndex, 1);

      if (!movedItem) return;

      currentSorting.splice(toIndex, 0, movedItem);

      criteria.clearSort();
      currentSorting.forEach((sort) => {
        criteria.addSort(sort.field as FieldPath<T>, sort.direction);
      });
    },
    [criteria]
  );

  return {
    updateSort,
    reorderSort,
  };
}
